// ═══ PWA AUTO-UPDATE — one deploy updates every device ═══════════════════════
// Checks for a new version on app open / foreground / every 30 min, then
// reloads silently once the new service worker takes control. No manual
// cache-clearing needed on any device after this ships.
if (typeof window !== "undefined" && "serviceWorker" in navigator) {
  let hadController = !!navigator.serviceWorker.controller;
  let refreshing = false;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (!hadController) { hadController = true; return; } // first-ever install — don't reload
    if (refreshing) return;
    refreshing = true;
    window.location.reload();
  });
  const checkUpdate = () => navigator.serviceWorker.getRegistration()
    .then(reg => { if (reg) reg.update(); })
    .catch(() => {});
  // When the installed app is opened or brought back to foreground (phones)
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") checkUpdate();
  });
  // While the app stays open
  setInterval(checkUpdate, 30 * 60 * 1000);
  // Shortly after launch
  setTimeout(checkUpdate, 10 * 1000);
}

