// ── Number to words (module-level — shared by all document builders) ──
const toWords=(n)=>{
  if(!n||n===0)return"Zero Rupees Only";
  const a=["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
  const b=["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
  const t=(x,s)=>{if(x===0)return"";if(x<20)return a[x]+(s?" "+s:"")+" ";if(x<100)return b[Math.floor(x/10)]+(x%10?" "+a[x%10]:"")+(s?" "+s:"")+" ";return a[Math.floor(x/100)]+" Hundred "+(x%100?t(x%100,""):"")+(s?" "+s+" ":"");};
  const cr=Math.floor(n/10000000),la=Math.floor((n%10000000)/100000),th=Math.floor((n%100000)/1000),hu=n%1000;
  return((cr?t(cr,"Crore"):"")+(la?t(la,"Lakh"):"")+(th?t(th,"Thousand"):"")+(hu?t(hu,""):"")||"Zero")+" Rupees Only";
};

