// ── Editable Business Profile (§2) ────────────────────────────
// CO holds the live company info used across all documents. We keep CO as a
// mutable object so every existing CO.* reference keeps working, and simply
// merge any saved profile over it: first from a local cache (instant, offline),
// then from Supabase on app start. The form lives in Settings → Business.
const BIZ_CACHE_KEY = "apc_business_profile";
const applyBusinessProfile = (p) => {
  if (p && typeof p === "object") {
    // Never blank-out a field with an empty value from the saved profile
    Object.keys(p).forEach(k => { if (p[k] !== "" && p[k] != null) CO[k] = p[k]; });
  }
  return CO;
};
try { applyBusinessProfile(JSON.parse(localStorage.getItem(BIZ_CACHE_KEY) || "{}")); } catch {}

// ── Send in-app + WhatsApp notification for order salary ──────
// ── Send in-app + WhatsApp notification for order salary ──────
// Auto-sends via Meta Cloud API (staffPayment template) with Earned/Advance/Net summary.
// Falls back to opening WhatsApp manually if template not configured or send fails.
const notifyOrderSalary = async (staffId, staffName, staffPhone, salary, orderId, customer, moveDate, ordersList=[], staffList=[]) => {
  // Cloud in-app notification — reaches the staff member's OWN device
  DB.addStaffNotif({staffId,type:"order_salary",title:"💰 Salary Updated!",message:`₹${Number(salary).toLocaleString("en-IN")} set for order: ${customer}`,amount:salary,orderId});
  // In-app notification
  try{
    const key=`apc_staff_notif_${staffId}`;
    const existing=JSON.parse(localStorage.getItem(key)||"[]");
    existing.unshift({
      id:Date.now(),
      type:"order_salary",
      title:"💰 Salary Updated!",
      message:`₹${Number(salary).toLocaleString("en-IN")} set for order: ${customer}`,
      amount:Number(salary),
      orderId,
      customer,
      moveDate,
      ts:new Date().toISOString(),
      read:false
    });
    localStorage.setItem(key,JSON.stringify(existing.slice(0,20)));
  }catch{}
  // WhatsApp notification — Cloud API first, manual fallback
  if(staffPhone){
    // Earned this month (substituting the just-saved salary for this order)
    const earned=ordersList.filter(o=>{
      const d=new Date(o.move_date);
      return d.getMonth()===TODAY.getMonth()&&d.getFullYear()===TODAY.getFullYear()&&(o.order_staff||[]).some(os=>os.staff_id===staffId);
    }).reduce((sum,o)=>sum+(o.order_staff||[]).filter(os=>os.staff_id===staffId).reduce((a,e)=>a+(o.id===orderId?(Number(salary)||0):(e.salary_amount||0)),0),0);
    const advance=Number(staffList.find(x=>x.id===staffId)?.advance||0);
    const netBalance=earned-advance;

    const waRes=await WA.staffPayment(staffName,staffPhone,"order_salary",Number(salary)||0,earned,advance,netBalance);
    if(waRes?.ok){
      toast(`📱 WhatsApp sent to ${staffName}!`,"success");
    } else {
      // No template configured or API failure → open WhatsApp manually
      if(waRes?.reason&&waRes.reason!=="no_template")toast(`WA API failed (${waRes.reason}) — opening WhatsApp`,"warn");
      const msg=`Hi ${staffName.split(" ")[0]}! 👷 ${CO.name}\n\n*Salary Updated* 💰\nOrder: ${orderId}\nCustomer: ${customer}\nDate: ${moveDate||"—"}\nYour Salary: ₹${Number(salary).toLocaleString("en-IN")}\n\n📊 This Month:\n• Earned: ${fmt.inr(earned)}\n• Advance: ${fmt.inr(advance)}\n• Net Balance: ${fmt.inr(netBalance)}\n\nThank you for your hard work! 🙏`;
      openWABusiness(staffPhone,msg);
    }
  }
};
// Uses Android intent to open com.whatsapp.w4b, falls back to wa.me
const openWABusiness = (phone, message) => {
  const clean = String(phone||"").replace(/\D/g,"");
  const num = clean.startsWith("91") ? clean : `91${clean}`;
  const encoded = encodeURIComponent(message||"");
  const isAndroid = /android/i.test(navigator.userAgent);
  if(isAndroid){
    window.location.href = `intent://send/${num}#Intent;scheme=whatsapp;package=com.whatsapp.w4b;S.browser_fallback_url=https%3A%2F%2Fwa.me%2F${num}%3Ftext%3D${encoded};end`;
  } else {
    window.open(`https://wa.me/${num}?text=${encoded}`,"_blank");
  }
};

