const DEFAULT_PORTER_RATES = {local:16, outstation:19};

// Runtime config — loaded from localStorage, falls back to defaults
const loadCftRanges = () => { try { const s=localStorage.getItem("apc_cft_ranges"); return s?JSON.parse(s):DEFAULT_CFT_RANGES; } catch { return DEFAULT_CFT_RANGES; } };
const loadPackages  = () => { try { const s=localStorage.getItem("apc_packages");   return s?JSON.parse(s):DEFAULT_PACKAGES;   } catch { return DEFAULT_PACKAGES;   } };
const loadPorterRates = () => { try { const s=localStorage.getItem("apc_porter_rates"); return s?JSON.parse(s):DEFAULT_PORTER_RATES; } catch { return DEFAULT_PORTER_RATES; } };

let CFT_RANGES = loadCftRanges();
let PACKAGES   = loadPackages();
let PORTER_RATES = loadPorterRates();

const reloadConfig = () => { CFT_RANGES=loadCftRanges(); PACKAGES=loadPackages(); PORTER_RATES=loadPorterRates(); };

const getPkgFromCft = (cft) => {
  const range = CFT_RANGES.find(r => cft <= (r.max===null||r.max===undefined?Infinity:r.max));
  return range?.pkg || "4 BHK Big";
};

