  async getAddons(){ const {data}=await db.from("order_addons").select("*").order("created_at",{ascending:false}); return data||[]; },
  async addAddon(a){ const {data,error}=await db.from("order_addons").insert(a).select().single(); if(error)throw error; return data; },
