  async addOrder(o,teams) {
    const id=`APC${Date.now()}`;
    const {data,error}=await db.from("orders").insert([{id,customer:o.customer,phone:o.phone||"",from_city:o.from,to_city:o.to,from_address:o.fromAddr||"",to_address:o.toAddr||"",from_floor:Number(o.fromFloor)||0,to_floor:Number(o.toFloor)||0,move_date:o.date,move_time:o.moveTime||null,amount:Number(o.amount)||0,quote_amount:Number(o.amount)||0,order_type:o.orderType||"local",distance_km:Number(o.distanceKm)||0,status:o.status||"pending",service:o.service||"Home Shifting",branch:o.branch||"Chennai",notes:o.notes||"",lead_id:o.leadId||null,quotation_id:o.quotationId||null,advance_paid:Number(o.advancePaid)||0,booking_advance:Number(o.advancePaid)||0,payment_status:o.paymentStatus||"pending",order_source:o.orderSource||"direct",vehicle_no:o.vehicleNo||"",driver_name:o.driverName||"",vehicle_id:o.vehicleId||null,third_party_vehicle:!!o.thirdParty,start_km:o.startKm?Number(o.startKm):null,end_km:o.endKm?Number(o.endKm):null,supervisor_id:o.supervisorId||null,order_complete:false,wa_muted:o.orderSource==="porter",porter_cash_collect:o.orderSource==="porter"?Number(o.porterCashCollect)||0:0}]).select();
    if (error||!data?.[0]) { console.error("addOrder",error?.message); return null; }
    if (teams?.length) {
      const {error:se}=await db.from("order_staff").upsert(
        teams.map(t=>({order_id:id,staff_id:t.staffId,salary_amount:Number(t.salary)||0,is_half_day:t.halfDay||false,team_type:t.teamType||"full"})),
        {onConflict:"order_id,staff_id"}
      );
      if(se) console.error("addOrder staff upsert",se.message);
    }
    return data[0];
  },
  async updateOrder(id,f) {
    const {error}=await db.from("orders").update(f).eq("id",id);
    if(error) { console.error("updateOrder",error.message); return false; }
    return true;
  },
  async markOrderComplete(id,complete) { await db.from("orders").update({order_complete:complete}).eq("id",id); },
  async updateOrderStaff(orderId,teams) {
    // Step 1: delete existing staff for this order
    const {error:de}=await db.from("order_staff").delete().eq("order_id",orderId);
    if(de) { console.error("delete order_staff",de.message); return false; }
    // Step 2: insert updated salary records
    if (teams?.length) {
      const rows=teams.map(t=>({
        order_id:orderId,
        staff_id:t.staffId,
        salary_amount:Number(t.salary)||0,
        is_half_day:t.halfDay||false,
        team_type:t.teamType||"full"
      }));
      const {error:ie}=await db.from("order_staff").insert(rows);
      if(ie) {
        console.error("insert order_staff",ie.message);
        // fallback: try upsert if insert fails
        const {error:ue}=await db.from("order_staff").upsert(rows,{onConflict:"order_id,staff_id"});
        if(ue) { console.error("upsert order_staff fallback",ue.message); return false; }
      }
    }
    return true;
  },
