  async assignSupervisor(orderId, supervisorId) {
    const { error } = await db.from("orders").update({
      supervisor_id: supervisorId,
      assigned_at: new Date().toISOString(),
      status: 'assigned'
    }).eq("id", orderId);
    if (error) console.error("assignSupervisor failed:", error);
    return !error;
  },
  async updateOrderStatus(orderId, newStatus, extras = {}) {
    const stamps = {};
    if (newStatus === 'accepted') stamps.accepted_at = new Date().toISOString();
    if (newStatus === 'loading') stamps.loading_started_at = new Date().toISOString();
    if (newStatus === 'in_transit') stamps.transit_started_at = new Date().toISOString();
    if (newStatus === 'unloading') stamps.unloading_started_at = new Date().toISOString();
    if (newStatus === 'delivered') stamps.delivered_at = new Date().toISOString();
    if (newStatus === 'pending_review') stamps.submitted_at = new Date().toISOString();
    if (newStatus === 'closed') stamps.closed_at = new Date().toISOString();
    const { error } = await db.from("orders").update({ status: newStatus, ...stamps, ...extras }).eq("id", orderId);
    if (error) console.error("updateOrderStatus failed:", error);
    return !error;
  },
  async addFieldExpense(orderId, expense) {
    // SINGLE SOURCE OF TRUTH: write to expenses table (shows in Expenses module + order P&L),
    // mirror in order.field_expenses with linked exp_id for the supervisor panel display
    let expRow = null;
    try {
      const { data, error: e1 } = await db.from("expenses").insert([{
        order_id: orderId,
        category: `Field — ${expense.type || "Misc"}`,
        amount: Number(expense.amount) || 0,
        description: (expense.note || "").trim() || "Field expense (supervisor)",
        expense_date: new Date().toISOString().split("T")[0]
      }]).select().single();
      if (e1) console.error("field expense → expenses table failed:", e1);
      else expRow = data;
    } catch (err) { console.error(err); }
    const { data: cur } = await db.from("orders").select("field_expenses").eq("id", orderId).single();
    const exp = Array.isArray(cur?.field_expenses) ? cur.field_expenses : [];
    const newExp = [...exp, { ...expense, exp_id: expRow?.id || null, at: new Date().toISOString() }];
    const { error } = await db.from("orders").update({ field_expenses: newExp }).eq("id", orderId);
    if (error) console.error("addFieldExpense failed:", error);
    return !error;
  },
  async removeFieldExpense(orderId, idx) {
    const { data: cur } = await db.from("orders").select("field_expenses").eq("id", orderId).single();
    const exp = Array.isArray(cur?.field_expenses) ? cur.field_expenses : [];
    const target = exp[idx];
    if (target?.exp_id) { try { await db.from("expenses").delete().eq("id", target.exp_id); } catch {} }
    const newExp = exp.filter((_, i) => i !== idx);
    await db.from("orders").update({ field_expenses: newExp }).eq("id", orderId);
  },
  async getNextInvoiceNo(prefix="APC") {
    const fy=()=>{const n=new Date();const y=n.getFullYear();return n.getMonth()>=3?`${String(y).slice(-2)}${String(y+1).slice(-2)}`:`${String(y-1).slice(-2)}${String(y).slice(-2)}`;};
    const key=`inv_seq_${prefix}_${fy()}`;
    try{
      const {data,error}=await db.from("settings").select("value").eq("key",key).single();
      const next=(data?.value?Number(data.value):0)+1;
      await db.from("settings").upsert({key,value:String(next)},{onConflict:"key"});
      return `${prefix}/${fy()}/${String(next).padStart(3,"0")}`;
    }catch{return `${prefix}/${fy()}/${Date.now().toString().slice(-4)}`;}
  },
